describe('epoch', () => {
  it('CORE-EPOCH-004 CORE-EPOCH-005 CORE-VISIBLE-008 AC-F3-10 a server restart clears sent and received messages, keeps and delivers pending ones', async () => {
    const world = makeWorld();
    const alice = await loggedInOnline('alice', world);
    alice.engine.send('bob', 'A1');
    world.server.inject({ id: '00000000-0000-4000-8000-0000000000b1', from: 'bob', to: 'alice', type: 'text', payload: { text: 'B1' } });
    await world.time.runUntil(() => view(alice).length === 2 && snap(alice).outbox.length === 0);
    const oldEpoch = snap(alice).epoch;
    alice.transport.mode = 'down';
    await world.time.runUntil(() => snap(alice).connection === 'connecting');
    alice.engine.send('bob', 'A3');
    world.server.restart();
    alice.transport.mode = 'up';
    await world.time.runUntil(() => snap(alice).outbox.length === 0);
    expect(snap(alice).epoch).not.toBe(oldEpoch);
    expect(view(alice)).toEqual(['A3(sent,1)']);
    expect(alice.log.lines).toEqual([]);
  });

  it('CORE-EPOCH-005 on 409 epoch_mismatch nothing stored changes and the next cycle starts with a session', async () => {
    const world = makeWorld();
    const alice = await loggedInOnline('alice', world);
    const before = alice.store.data;
    alice.transport.override = (e) =>
      e === 'E4' ? { kind: 'response', status: 409, body: { error: { code: 'epoch_mismatch', message: 'x' } } } : undefined;
    const n = alice.transport.calls.length;
    await world.time.advance(1000);
    expect(alice.store.data).toBe(before);
    expect(snap(alice).connection).toBe('connecting');
    alice.transport.override = null;
    await world.time.advance(1000);
    expect(alice.transport.calls[n + 1].endpoint).toBe('E2');
  });

  it('CORE-SESSION-004 a session answering another name is a failed request', async () => {
    const world = makeWorld();
    const c = makeClient(world);
    c.transport.override = (e) =>
      e === 'E2' ? { kind: 'response', status: 200, body: { name: 'mallory', epoch: world.server.epoch, new_user: true } } : undefined;
    c.engine.login('alice');
    await world.time.advance(2500);
    expect(c.transport.endpoints()).toEqual(['E2', 'E2', 'E2']);
    expect(snap(c).connection).toBe('connecting');
    expect(snap(c).epoch).toBeNull();
  });
});

describe('relaunch and snapshot', () => {
  it('CORE-LOGIN-005 CORE-OFFLINE-004 CORE-OUTBOX-002 PLAT-HOOK-011 relaunch keeps identity and pending order, the switch starts off', async () => {
    const world = makeWorld();
    let c = makeClient(world);
    c.transport.mode = 'down';
    c.engine.login('Carol');
    c.engine.setOffline(true);
    c.engine.send('Dave', 'first');
    c.engine.send('Dave', 'second');
    c = relaunch(c);
    c.transport.mode = 'down';
    const s = snap(c);
    expect(s.user).toBe('carol');
    expect(s.offline_toggle).toBe(false);
    expect(view(c)).toEqual(['first(pending,-)', 'second(pending,-)']);
    c.transport.mode = 'up';
    await world.time.runUntil(() => snap(c).outbox.length === 0);
    expect(view(c)).toEqual(['first(sent,1)', 'second(sent,2)']);
  });

  it('PLAT-HOOK-007 PLAT-HOOK-008 PLAT-HOOK-013 the snapshot reflects persisted state in CORE-SEQ-002 order', async () => {
    const world = makeWorld();
    const c = await loggedInOnline('alice', world);
    c.timeZone.offsetMinutes = -180;
    c.engine.send('bob', 'one');
    await world.time.runUntil(() => snap(c).outbox.length === 0);
    c.engine.setOffline(true);
    c.engine.send('bob', 'two');
    const s = snap(c);
    const stored = c.store.load();
    expect(s.outbox).toEqual(stored?.outbox);
    expect(s.cursor).toBe(stored?.cursor);
    expect(s.epoch).toBe(stored?.epoch);
    expect(s.messages.map((m) => [m.text, m.state, m.seq, m.time_text])).toEqual([
      ['one', 'sent', 1, '12:00'],
      ['two', 'pending', null, null],
    ]);
    expect(s.messages[0].accepted_at).toBe(stored?.messages[0].accepted_at);
  });

  it('PLAT-WEB-005 getSnapshot returns the same object until state changes', async () => {
    const world = makeWorld();
    const c = await loggedInOnline('alice', world);
    const a = c.engine.getSnapshot();
    expect(c.engine.getSnapshot()).toBe(a);
    let notified = 0;
    const off = c.engine.subscribe(() => {
      notified += 1;
    });
    c.engine.setOffline(true);
    expect(notified).toBeGreaterThan(0);
    expect(c.engine.getSnapshot()).not.toBe(a);
    off();
  });

  it('CORE-EXT-003 only the core type text is sent', async () => {
    const world = makeWorld();
    const c = await loggedInOnline('alice', world);
    c.engine.send('bob', 'x');
    await world.time.runUntil(() => snap(c).outbox.length === 0);
    expect(world.server.mailbox('bob').map((e) => e.type)).toEqual(['text']);
  });
});
